-- Adicionar campo action na tabela role_permissions
ALTER TABLE role_permissions ADD COLUMN action VARCHAR(20) NOT NULL DEFAULT 'view' AFTER submodule;

-- Renomear campo permission para permission_level e converter para ENUM
ALTER TABLE role_permissions 
  CHANGE COLUMN permission permission_level ENUM('total', 'readonly', 'none') NOT NULL;

-- Adicionar índice único para evitar duplicatas (role_id + module + submodule + action)
ALTER TABLE role_permissions 
  ADD UNIQUE KEY unique_permission (role_id, module, submodule, action);

